#!/usr/bin/env bash
# Night light (wlsunset). No arg: toggle. "status": waybar JSON.  (generated by theme.py)
# Keep both temperatures warm; wlsunset requires the high value to exceed the low value.
if [ "${1:-}" = status ]; then
  pgrep -x wlsunset >/dev/null && echo '{"text":"󰖔","class":"on","tooltip":"Night light ON (Super+F11)"}' \
                                || echo '{"text":"󰖨","class":"off","tooltip":"Night light off (Super+F11)"}'; exit 0
fi
if pkill -x wlsunset; then notify-send -t 1500 "Night light" "Off"
else setsid -f wlsunset -t 4000 -T 4001 -S 06:30 -s 19:00 >/dev/null 2>&1; notify-send -t 1500 "Night light" "On until you turn it off"; fi
